<?php
namespace App\Domains\Metadata\Http\Controllers;
use App\Domains\Metadata\Models\{DataDictionaryEntry,DataQualityRule,DataRetentionPolicy}; use App\Domains\Platform\Contracts\TenantContext; use Illuminate\Http\{JsonResponse,Request};
class DataGovernanceController { public function __construct(private readonly TenantContext $tenant){} private function allow(Request $r,string $p):void{$r->user()->hasPermission($p)||abort(403);} public function dictionary(Request $r):JsonResponse{$this->allow($r,'metadata.view');return response()->json(['data'=>DataDictionaryEntry::query()->where(fn($q)=>$q->whereNull('tenant_id')->orWhere('tenant_id',$this->tenant->id()))->when($r->query('table_name'),fn($q,$v)=>$q->where('table_name',$v))->paginate(50)]);} public function storeDictionary(Request $r):JsonResponse{$this->allow($r,'metadata.manage');$d=$r->validate(['domain'=>['required','string'],'entity_name'=>['required','string'],'table_name'=>['required','string'],'column_name'=>['required','string'],'display_name'=>['nullable','string'],'business_description'=>['nullable','string'],'technical_description'=>['nullable','string'],'data_type'=>['required','string'],'classification'=>['required','in:public,internal,confidential,restricted,highly_restricted'],'validation_rules'=>['nullable','array'],'business_rules'=>['nullable','array'],'api_mapping'=>['nullable','array'],'search_mapping'=>['nullable','array'],'analytics_mapping'=>['nullable','array'],'ai_mapping'=>['nullable','array'],'localizations'=>['nullable','array'],'contains_pii'=>['sometimes','boolean'],'encryption_required'=>['sometimes','boolean'],'masking_required'=>['sometimes','boolean']]);return response()->json(['data'=>DataDictionaryEntry::query()->updateOrCreate(['tenant_id'=>$this->tenant->id(),'table_name'=>$d['table_name'],'column_name'=>$d['column_name']],$d)],201);} public function rules(Request $r):JsonResponse{$this->allow($r,'metadata.view');return response()->json(['data'=>DataQualityRule::query()->where(fn($q)=>$q->whereNull('tenant_id')->orWhere('tenant_id',$this->tenant->id()))->paginate(25)]);} public function retention(Request $r):JsonResponse{$this->allow($r,'metadata.view');return response()->json(['data'=>DataRetentionPolicy::query()->where(fn($q)=>$q->whereNull('tenant_id')->orWhere('tenant_id',$this->tenant->id()))->paginate(25)]);} }
